TABLES = [
    {'name': 'dim_customer', 'rows': 500000, 'type': 'dimension'},
    {'name': 'fact_sales', 'rows': 2000000000, 'type': 'fact', 'hash_col': 'sale_id'},
    {'name': 'stg_raw', 'rows': 50000000, 'type': 'staging'},
]

def strategy(table):
    if table.get('type') == 'dimension' and table.get('rows', 0) < 1000000:
        return 'REPLICATE'
    if table.get('type') == 'fact' and table.get('hash_col'):
        return f"HASH({table['hash_col']})"
    return 'ROUND_ROBIN'

for t in TABLES:
    print(f"{t['name']} -> {strategy(t)}")
